CREATE OR REPLACE WAREHOUSE REGINTEL360_WH WAREHOUSE_SIZE='XSMALL' AUTO_SUSPEND=60 AUTO_RESUME=TRUE;
CREATE OR REPLACE DATABASE REGINTEL360;
CREATE OR REPLACE SCHEMA REGINTEL360.RISK;
USE DATABASE REGINTEL360; USE SCHEMA RISK;
CREATE OR REPLACE TABLE TRANSACTIONS (TRANSACTION_ID STRING, CUSTOMER_ID STRING, TRANSACTION_TS TIMESTAMP_NTZ, COUNTRY STRING, CURRENCY STRING, AMOUNT NUMBER(18,2), CHANNEL STRING, MERCHANT_CATEGORY STRING, PAYMENT_METHOD STRING, LABEL STRING);
CREATE OR REPLACE TABLE REGULATORY_DOCUMENTS (DOCUMENT_ID STRING, TITLE STRING, DOMAIN STRING, AUTHORITY STRING, EFFECTIVE_DATE DATE, CONTENT STRING);
CREATE OR REPLACE TABLE RISK_ALERTS (ALERT_ID STRING, TRANSACTION_ID STRING, CUSTOMER_ID STRING, PATTERN STRING, RISK_SCORE NUMBER(5,2), REASON STRING, CREATED_AT TIMESTAMP_NTZ);
